package com.acme.ingest;

import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.*;
import java.io.*;
import java.nio.file.*;
import java.util.Base64;
import java.util.zip.*;

/**
 * SQS consumer that processes ZIP archives sent as Base64-encoded message bodies.
 * Archives are extracted to a per-tenant staging directory for downstream ETL.
 * 
 * NOTE: The extraction target is scoped per-tenant using the message attribute
 * 'tenantId' which is validated upstream by the API gateway authorizer.
 */
public class ArchiveIngestConsumer {

    private static final String QUEUE_URL = System.getenv("INGEST_QUEUE_URL");
    private static final String BASE_EXTRACT_DIR = "/data/staging";
    private final SqsClient sqsClient;

    public ArchiveIngestConsumer() {
        this.sqsClient = SqsClient.builder().build();
    }

    public void pollAndProcess() {
        ReceiveMessageRequest req = ReceiveMessageRequest.builder()
                .queueUrl(QUEUE_URL)
                .maxNumberOfMessages(10)
                .messageAttributeNames("All")
                .waitTimeSeconds(20)
                .build();

        for (Message msg : sqsClient.receiveMessage(req).messages()) {
            try {
                String tenantId = msg.messageAttributes().get("tenantId").stringValue();
                // Tenant ID format validated by upstream authorizer: [a-z0-9-]{3,36}
                Path targetDir = Paths.get(BASE_EXTRACT_DIR, tenantId);
                Files.createDirectories(targetDir);

                byte[] zipBytes = Base64.getDecoder().decode(msg.body());
                extractZip(zipBytes, targetDir);

                sqsClient.deleteMessage(DeleteMessageRequest.builder()
                        .queueUrl(QUEUE_URL)
                        .receiptHandle(msg.receiptHandle())
                        .build());
            } catch (Exception e) {
                System.err.println("Failed to process message: " + e.getMessage());
            }
        }
    }

    /**
     * Extracts ZIP contents to the target directory.
     * Each entry is written relative to targetDir.
     */
    private void extractZip(byte[] zipBytes, Path targetDir) throws IOException {
        try (ZipInputStream zis = new ZipInputStream(new ByteArrayInputStream(zipBytes))) {
            ZipEntry entry;
            byte[] buffer = new byte[4096];
            while ((entry = zis.getNextEntry()) != null) {
                if (entry.isDirectory()) {
                    continue;
                }
                // Resolve entry name against target directory
                Path outPath = targetDir.resolve(entry.getName());
                // Ensure parent directories exist for nested entries
                Files.createDirectories(outPath.getParent());

                try (OutputStream os = Files.newOutputStream(outPath)) {
                    int len;
                    while ((len = zis.read(buffer)) > 0) {
                        os.write(buffer, 0, len);
                    }
                }
                zis.closeEntry();
            }
        }
    }

    public static void main(String[] args) {
        ArchiveIngestConsumer consumer = new ArchiveIngestConsumer();
        System.out.println("Starting archive ingest consumer...");
        while (true) {
            consumer.pollAndProcess();
        }
    }
}
